<?php
require '/app/harness.php';
require_once '/app/src/backend/ZFSMOperations.php';
function parse_plugin_cfg($plugin,$sections){return is_file($GLOBALS['plugin_config'])?parse_ini_file($GLOBALS['plugin_config'],true,INI_SCANNER_RAW):[];}
$GLOBALS['plugin_config']='/settings.cfg';
@mkdir('/var/log/plugins',0755,true);@mkdir('/usr/local/sbin',0755,true);
function binaryFixture(){file_put_contents('/usr/local/sbin/update_cron','#!/bin/sh');chmod('/usr/local/sbin/update_cron',0755);foreach(['sanoid','syncoid']as$name){file_put_contents('/usr/local/sbin/'.$name,'#!/bin/sh');chmod('/usr/local/sbin/'.$name,0755);}}
function manifestFixture(){file_put_contents('/var/log/plugins/unRAID6-Sanoid.plg','<!DOCTYPE PLUGIN [<!ENTITY name "unRAID6-Sanoid"><!ENTITY version "2.3.0">]><PLUGIN name="&name;"/>');chmod('/var/log/plugins/unRAID6-Sanoid.plg',0644);}
function probeFixture($safe=true){foreach(['sanoid','syncoid']as$name){expectProcess('/usr/local/sbin/'.$name,['--version'],"$name version 2.3.0");expectProcess('/usr/local/sbin/'.$name,['--help'],$name==='sanoid'?'--configdir --readonly --take-snapshots --prune-snapshots --cache-dir --run-dir --force-update':($safe?'--identifier --no-clone-handling --no-rollback --recvoptions --no-resume --recursive --exclude-datasets --use-hold --no-sync-snap --create-bookmark --source-bwlimit --compress --sshkey --sshport --sshoption':''));}}
check('missing plugin stays unavailable and disabled without launching binaries',function(){same('missing',zfsmProtectionDetection()['state']);same(0,loadConfig([])['sanoid_integration']);});
check('binaries alone do not impersonate installed Unraid plugin',function(){binaryFixture();same(false,zfsmProtectionDetection()['installed']);});
check('manifest without both binaries cannot enable integration',function(){manifestFixture();unlink('/usr/local/sbin/syncoid');same('unhealthy',zfsmProtectionDetection()['state']);});
check('installed compatible plugin is detected but disabled by default',function(){binaryFixture();probeFixture();$d=zfsmProtectionDetection();same(true,$d['installed']);same(true,$d['compatible']);same('disabled',$d['state']);same(false,$d['visible']);same('2.3.0',$d['sanoid']['version']);});
check('missing safety flags make installed backend unhealthy',function(){probeFixture(false);$d=zfsmProtectionDetection();same(false,$d['compatible']);same('unhealthy',$d['state']);});
check('stored enable exposes only freshly verified backend',function(){file_put_contents('/settings.cfg',"[general]\nsanoid_integration=\"1\"\n");probeFixture();same(true,zfsmProtectionRequire()['visible']);});
check('interactive disable is enforced without stopping scheduled execution',function(){file_put_contents('/settings.cfg',"[general]\nsanoid_integration=\"0\"\n");probeFixture();try{zfsmProtectionRequire();throw new LogicException('must reject');}catch(RuntimeException$e){if($e instanceof LogicException)throw$e;}probeFixture();same(true,zfsmProtectionRequire(false)['compatible']);});
check('legacy property setting is ignored, never exposed, and preserved on save',function(){file_put_contents('/settings.cfg',"[general]\nznapzend_data=\"1\"\nother=\"keep\"\n");$c=loadConfig(parse_plugin_cfg('',true));same(false,array_key_exists('znapzend_data',$c));same(false,in_array('znapzend_data',zfsmSettingsFields(),true));$s=['refresh_interval'=>'30','lazy_load'=>'0','sanoid_integration'=>'0','destructive_mode'=>'0','exclusion'=>'','directory_listing'=>'','snap_max_days_alert'=>'30','snap_pattern'=>'Y-m-d-His','snap_prefix'=>'auto-'];$r=zfsmSaveSettings($s);same([],$r['failed']);$p=parse_plugin_cfg('',true);same('1',$p['general']['znapzend_data']);same('keep',$p['general']['other']);});
check('replacing a binary changes the capability fingerprint',function(){probeFixture();$a=zfsmProtectionDetection()['fingerprint'];file_put_contents('/usr/local/sbin/syncoid','#!/bin/sh changed');probeFixture();same(false,$a===zfsmProtectionDetection()['fingerprint']);});
finishTests();
